  while (c->pkenc_list)
    {
      struct pubkey_enc_list *tmp = c->pkenc_list->next;

      mpi_release (c->pkenc_list->data[0]);
      mpi_release (c->pkenc_list->data[1]);
      xfree (c->pkenc_list);
      c->pkenc_list = tmp;
    }
  c->pkenc_list = NULL;
  c->list = NULL;
  c->any.data = 0;
  c->any.uncompress_failed = 0;
  c->last_was_session_key = 0;
  c->seen_pkt_encrypted_aead = 0;
  xfree (c->dek);
  c->dek = NULL;
}


static int
